const Explanation *find_explanation(std::string_view topic) noexcept {
    if (topic == "last") topic = "agent-offline";
    for (const Explanation &entry : kExplanations) {
        if (entry.key == topic) return &entry;
    }
    return nullptr;
}

std::optional<std::string_view> explanation_hint_for_text(
    std::string_view text) noexcept {
    if (text.find("libsodium") != std::string_view::npos) {
        return "missing-libsodium";
    }
    if (text.find("not a current Tox friend") != std::string_view::npos ||
        text.find("friend") != std::string_view::npos) {
        return "friendship-not-authority";
    }
    if (text.find("namespace") != std::string_view::npos &&
        text.find("invalid") != std::string_view::npos) {
        return "invalid-namespace";
    }
    if (text.find("symlink") != std::string_view::npos ||
        text.find("special") != std::string_view::npos ||
        text.find("ACL") != std::string_view::npos ||
        text.find("xattr") != std::string_view::npos) {
        return "sync-source-symlink";
    }
    if (text.find("permission") != std::string_view::npos ||
        text.find("owner") != std::string_view::npos) {
        return "permission-denied";
    }
    if (text.find("route") != std::string_view::npos ||
        text.find("fallback") != std::string_view::npos) {
        return "route-fallback-forbidden";
    }
    return std::nullopt;
}

void print_explanation_record(const Explanation &entry) {
    std::cout << "iotox-explain-v1\n"
              << "topic=" << entry.key << '\n'
              << "problem=" << entry.problem << '\n'
              << "why=" << entry.why << '\n'
              << "safe-next=" << entry.safe_next << '\n'
              << "doc=" << entry.doc << '\n'
              << "boundary=" << entry.boundary << '\n';
}

int run_explain(std::span<const std::string_view> arguments) {
    if (arguments.size() != 2U) {
        std::cerr << "explain requires one topic\nknown topics:";
        for (const Explanation &entry : kExplanations) {
            std::cerr << ' ' << entry.key;
        }
        std::cerr << " last\n";
        return 2;
    }
    const Explanation *entry = find_explanation(arguments[1U]);
    if (entry == nullptr) {
        std::cerr << "unknown explain topic: " << arguments[1U]
                  << "\nknown topics:";
        for (const Explanation &candidate : kExplanations) {
            std::cerr << ' ' << candidate.key;
        }
        std::cerr << " last\n";
        return 2;
    }
    print_explanation_record(*entry);
    if (arguments[1U] == "last") {
        std::cout << "last-error-store=not-implemented\n"
                  << "note=IoTox does not persist arbitrary local stderr; "
                     "use the named explain topics for stable hints.\n";
    }
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

Result<std::uint64_t> parse_u64(std::string_view text, std::string_view label) {
    if (text.empty() || text.front() == '-') {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " must be a non-negative integer"};
    }
    try {
        std::size_t consumed = 0U;
        const unsigned long long value = std::stoull(std::string(text), &consumed, 10);
        if (consumed != text.size()) {
            return Status{ErrorCode::invalid_argument,
                          std::string(label) + " contains trailing characters"};
        }
        return static_cast<std::uint64_t>(value);
    } catch (const std::exception &) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " must be a non-negative integer"};
    }
}

Result<terminal::CgroupIoDevice> parse_cgroup_io_device_argument(
    std::string_view text, std::string_view label) {
    const std::size_t separator = text.find(':');
    if (separator == std::string_view::npos || separator == 0U ||
        separator + 1U >= text.size() ||
        text.find(':', separator + 1U) != std::string_view::npos) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " must be canonical MAJOR:MINOR"};
    }
    const std::string_view major_text = text.substr(0U, separator);
    const std::string_view minor_text = text.substr(separator + 1U);
    const auto canonical_decimal = [](std::string_view value) noexcept {
        return !value.empty() && value.front() != '+' && value.front() != '-' &&
               (value.size() == 1U || value.front() != '0') &&
               std::all_of(value.begin(), value.end(), [](char character) {
                   return character >= '0' && character <= '9';
               });
    };
    if (!canonical_decimal(major_text) || !canonical_decimal(minor_text)) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " must be canonical MAJOR:MINOR"};
    }
    auto major = parse_u64(major_text, label);
    if (!major.ok()) return major.status();
    auto minor = parse_u64(minor_text, label);
    if (!minor.ok()) return minor.status();
    if (major.value() > std::numeric_limits<std::uint32_t>::max() ||
        minor.value() > std::numeric_limits<std::uint32_t>::max() ||
        (major.value() == 0U && minor.value() == 0U)) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " is outside the supported device range"};
    }
    return terminal::CgroupIoDevice{
        static_cast<std::uint32_t>(major.value()),
        static_cast<std::uint32_t>(minor.value())};
}

int hex_nibble(char value) {
    if (value >= '0' && value <= '9') {
        return value - '0';
    }
    if (value >= 'a' && value <= 'f') {
        return 10 + value - 'a';
    }
    if (value >= 'A' && value <= 'F') {
        return 10 + value - 'A';
    }
    return -1;
}

Result<std::vector<std::uint8_t>> decode_hex(std::string_view text) {
    if (text.size() % 2U != 0U) {
        return Status{ErrorCode::invalid_argument,
                      "hex input must contain an even number of characters"};
    }
    std::vector<std::uint8_t> output;
    output.reserve(text.size() / 2U);
    for (std::size_t index = 0U; index < text.size(); index += 2U) {
        const int high = hex_nibble(text[index]);
        const int low = hex_nibble(text[index + 1U]);
        if (high < 0 || low < 0) {
            return Status{ErrorCode::invalid_argument,
                          "hex input contains a non-hexadecimal character"};
        }
        output.push_back(static_cast<std::uint8_t>((high << 4) | low));
    }
    return output;
}

Result<security::SigningPublicKey> parse_signing_public_key(
    std::string_view text, std::string_view label) {
    auto decoded = security::decode_hex_exact(
        text, security::kSigningPublicKeyBytes, label);
    if (!decoded) {
        return decoded.status();
    }
    security::SigningPublicKey key{};
    std::copy(decoded.value().begin(), decoded.value().end(), key.begin());
    return key;
}

Result<security::Digest> parse_digest_argument(
    std::string_view text, std::string_view label) {
    auto decoded = security::decode_hex_exact(
        text, security::kDigestBytes, label);
    if (!decoded) {
        return decoded.status();
    }
    security::Digest digest{};
    std::copy(decoded.value().begin(), decoded.value().end(), digest.begin());
    return digest;
}

std::string escape_bytes(std::span<const std::uint8_t> bytes) {
    std::ostringstream output;
    output << std::hex << std::uppercase << std::setfill('0');
    for (const std::uint8_t value : bytes) {
        switch (value) {
            case '\\': output << "\\\\"; break;
            case '\n': output << "\\n"; break;
            case '\r': output << "\\r"; break;
            case '\t': output << "\\t"; break;
            default:
                if (value >= 0x20U && value <= 0x7EU) {
                    output << static_cast<char>(value);
                } else {
                    output << "\\x" << std::setw(2)
                           << static_cast<unsigned int>(value);
                }
                break;
        }
    }
    return output.str();
}

std::uint64_t next_request_id() {
    const auto ticks = std::chrono::steady_clock::now().time_since_epoch().count();
    std::uint64_t value = static_cast<std::uint64_t>(ticks);
    value ^= static_cast<std::uint64_t>(::getpid()) << 32U;
    return value == 0U ? 1U : value;
}

std::uint64_t unix_time_ms() {
    const auto now = std::chrono::system_clock::now().time_since_epoch();
    return static_cast<std::uint64_t>(
        std::chrono::duration_cast<std::chrono::milliseconds>(now).count());
}

void append_u32(std::vector<std::uint8_t> &output, std::uint32_t value) {
    output.push_back(static_cast<std::uint8_t>((value >> 24U) & 0xFFU));
    output.push_back(static_cast<std::uint8_t>((value >> 16U) & 0xFFU));
    output.push_back(static_cast<std::uint8_t>((value >> 8U) & 0xFFU));
    output.push_back(static_cast<std::uint8_t>(value & 0xFFU));
}

void append_u16(std::vector<std::uint8_t> &output, std::uint16_t value) {
    output.push_back(static_cast<std::uint8_t>((value >> 8U) & 0xFFU));
    output.push_back(static_cast<std::uint8_t>(value & 0xFFU));
}

void append_u64(std::vector<std::uint8_t> &output, std::uint64_t value) {
    for (int shift = 56; shift >= 0; shift -= 8) {
        output.push_back(static_cast<std::uint8_t>(
            (value >> static_cast<unsigned>(shift)) & 0xFFU));
    }
}

std::uint32_t read_u32(std::span<const std::uint8_t> bytes, std::size_t offset = 0U) {
    std::uint32_t value = 0U;
    for (std::size_t index = 0U; index < 4U; ++index) {
        value = static_cast<std::uint32_t>((value << 8U) | bytes[offset + index]);
    }
    return value;
}

std::uint16_t read_u16(
    std::span<const std::uint8_t> bytes, std::size_t offset = 0U) {
    return static_cast<std::uint16_t>(
        (static_cast<std::uint16_t>(bytes[offset]) << 8U) |
        static_cast<std::uint16_t>(bytes[offset + 1U]));
}

std::uint64_t read_u64(
    std::span<const std::uint8_t> bytes, std::size_t offset = 0U) {
    std::uint64_t value = 0U;
    for (std::size_t index = 0U; index < 8U; ++index) {
        value = (value << 8U) |
                static_cast<std::uint64_t>(bytes[offset + index]);
    }
    return value;
}

Result<std::uint32_t> parse_u32_argument(
    std::string_view text, std::string_view label) {
    auto parsed = parse_u64(text, label);
    if (!parsed || parsed.value() > std::numeric_limits<std::uint32_t>::max()) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " is outside the uint32 range"};
    }
    return static_cast<std::uint32_t>(parsed.value());
}

Result<std::filesystem::path> absolute_cli_path(
    std::string_view text, std::string_view label) {
    if (text.empty()) {
        return Status{ErrorCode::invalid_argument, std::string(label) + " is empty"};
    }
    std::error_code error;
    std::filesystem::path path = std::filesystem::absolute(
        std::filesystem::path(std::string(text)), error);
    if (error) {
        return Status{ErrorCode::invalid_argument,
                      "unable to make " + std::string(label) + " absolute: " +
                          error.message()};
    }
    path = path.lexically_normal();
    const std::string native = path.native();
    if (native.empty() || native.size() > 16U * 1024U) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " must contain 1..16384 bytes"};
    }
    return path;
}

bool path_has_lexical_prefix(const std::filesystem::path &root,
                             const std::filesystem::path &candidate) {
    auto root_component = root.begin();
    auto candidate_component = candidate.begin();
    for (; root_component != root.end();
         ++root_component, ++candidate_component) {
        if (candidate_component == candidate.end() ||
            *candidate_component != *root_component) {
            return false;
        }
    }
    return true;
}

std::string shell_quote(std::string_view value) {
    if (value.empty()) return "''";
    const auto safe = [](char character) noexcept {
        return (character >= 'A' && character <= 'Z') ||
               (character >= 'a' && character <= 'z') ||
               (character >= '0' && character <= '9') ||
               character == '_' || character == '-' || character == '.' ||
               character == '/' || character == ':' || character == ',' ||
               character == '=' || character == '+' || character == '@' ||
               character == '%';
    };
    if (std::all_of(value.begin(), value.end(), safe)) {
        return std::string(value);
    }
    std::string output{"'"};
    for (const char character : value) {
        if (character == '\'') {
            output += "'\\''";
        } else {
            output.push_back(character);
        }
    }
    output.push_back('\'');
    return output;
}

Result<std::vector<std::uint8_t>> read_regular_file_bounded(
    const std::filesystem::path &path, std::size_t maximum,
    std::string_view label) {
    const int descriptor = ::open(
        path.c_str(), O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
    if (descriptor < 0) {
        return Status{ErrorCode::io_error,
                      "unable to open " + std::string(label) + ": " +
                          std::strerror(errno)};
    }
    struct ScopedDescriptor {
        int value;
        ~ScopedDescriptor() {
            if (value >= 0) static_cast<void>(::close(value));
        }
    } scoped{descriptor};
    struct stat before {};
    if (::fstat(descriptor, &before) != 0 || !S_ISREG(before.st_mode) ||
        before.st_size < 0 ||
        static_cast<std::uint64_t>(before.st_size) > maximum) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) +
                          " must be one bounded no-follow regular file"};
    }
    std::vector<std::uint8_t> bytes;
    bytes.reserve(static_cast<std::size_t>(before.st_size));
    std::array<std::uint8_t, 4096U> buffer{};
    for (;;) {
        const ssize_t count = ::read(descriptor, buffer.data(), buffer.size());
        if (count > 0) {
            const std::size_t amount = static_cast<std::size_t>(count);
            if (amount > maximum - bytes.size()) {
                return Status{ErrorCode::invalid_argument,
                              std::string(label) + " exceeds its byte bound"};
            }
            bytes.insert(
                bytes.end(), buffer.begin(),
                buffer.begin() + static_cast<std::ptrdiff_t>(amount));
            continue;
        }
        if (count < 0 && errno == EINTR) continue;
        if (count < 0) {
            return Status{ErrorCode::io_error,
                          "unable to read " + std::string(label) + ": " +
                              std::strerror(errno)};
        }
        break;
    }
    struct stat after {};
    if (::fstat(descriptor, &after) != 0 ||
        before.st_dev != after.st_dev || before.st_ino != after.st_ino ||
        before.st_size != after.st_size ||
        before.st_mtim.tv_sec != after.st_mtim.tv_sec ||
        before.st_mtim.tv_nsec != after.st_mtim.tv_nsec ||
        before.st_ctim.tv_sec != after.st_ctim.tv_sec ||
        before.st_ctim.tv_nsec != after.st_ctim.tv_nsec ||
        bytes.size() != static_cast<std::size_t>(after.st_size)) {
        return Status{ErrorCode::io_error,
                      std::string(label) + " changed while it was read"};
    }
    return bytes;
}

Result<sync::PrincipalId> parse_sync_principal(std::string_view text) {
    auto decoded = security::decode_hex_exact(
        text, sync::PrincipalId{}.size(), "sync stable principal");
    if (!decoded) return decoded.status();
    sync::PrincipalId result{};
    std::copy(decoded.value().begin(), decoded.value().end(), result.begin());
    return result;
}

Result<std::vector<std::uint8_t>> read_standard_input_bounded(
    std::size_t maximum, std::string_view label, bool allow_empty = false) {
    std::vector<std::uint8_t> output;
    output.reserve(std::min<std::size_t>(maximum, 4096U));
    std::array<std::uint8_t, 4096U> buffer{};
    for (;;) {
        const ssize_t count = ::read(STDIN_FILENO, buffer.data(), buffer.size());
        if (count < 0 && errno == EINTR) {
            continue;
        }
        if (count < 0) {
            return Status{ErrorCode::io_error,
                          "unable to read " + std::string(label) + " from standard input: " +
                              std::strerror(errno)};
        }
        if (count == 0) {
            break;
        }
        const std::size_t size = static_cast<std::size_t>(count);
        if (size > maximum - output.size()) {
            return Status{ErrorCode::invalid_argument,
                          std::string(label) + " exceeds " +
                              std::to_string(maximum) + " bytes"};
        }
        output.insert(output.end(), buffer.begin(),
                      buffer.begin() + static_cast<std::ptrdiff_t>(size));
    }
    if (output.empty() && !allow_empty) {
        return Status{ErrorCode::invalid_argument,
                      std::string(label) + " may not be empty"};
    }
    return output;
}

void append_path(
    std::vector<std::uint8_t> &payload, const std::filesystem::path &path) {
    const std::string native = path.native();
    payload.insert(payload.end(), native.begin(), native.end());
}

struct SyncSetupTail {
    bool read_write{false};
    std::uint64_t interval_seconds{30U};
    bool projection_requested{false};
    sync::TreeV2ProjectionPolicy projection;
};

Result<SyncSetupTail> parse_sync_setup_tail(
    std::span<const std::string_view> arguments,
    bool allow_explicit_one_writer, std::string_view command) {
    SyncSetupTail result;
    std::size_t index = 0U;
    if (index < arguments.size() && arguments[index] == "read-write") {
        result.read_write = true;
        ++index;
    } else if (index < arguments.size() &&
               arguments[index] == "one-writer") {
        if (!allow_explicit_one_writer) {
            return Status{ErrorCode::invalid_argument,
                          std::string(command) +
                              " access may omit one-writer or select read-write"};
        }
        ++index;
    }
    if (index < arguments.size()) {
        auto interval = parse_u64(arguments[index], "sync interval");
        if (!interval || interval.value() < 1U ||
            interval.value() > 86400U) {
            return Status{ErrorCode::invalid_argument,
                          "sync interval must be 1..86400 seconds"};
        }
        result.interval_seconds = interval.value();
        ++index;
    }
    if (index == arguments.size()) return result;
    if (!result.read_write) {
        return Status{ErrorCode::invalid_argument,
                      std::string(command) +
                          " metadata and selection require read-write"};
    }
    result.projection_requested = true;
    const std::string_view metadata = arguments[index++];
    if (metadata == "executable-v1") {
        result.projection.metadata =
            sync::TreeV2MetadataMode::executable_v1;
    } else if (metadata == "owner-mode-v2") {
        result.projection.metadata = sync::TreeV2MetadataMode::owner_mode_v2;
    } else {
        return Status{ErrorCode::invalid_argument,
                      std::string(command) +
                          " metadata must be executable-v1 or owner-mode-v2"};
    }
    for (; index < arguments.size(); ++index) {
        const std::string_view rule = arguments[index];
        const bool include = rule.starts_with("include=");
        const bool exclude = rule.starts_with("exclude=");
        const std::string_view path =
            (include || exclude) ? rule.substr(8U) : std::string_view{};
        if ((!include && !exclude) ||
            !sync::valid_tree_v2_selection_path(path)) {
            return Status{ErrorCode::invalid_argument,
                          std::string(command) +
                              " selection rules require one canonical include=PATH or exclude=PATH"};
        }
        (include ? result.projection.includes : result.projection.excludes)
            .emplace_back(path);
    }
    std::sort(result.projection.includes.begin(),
              result.projection.includes.end());
    std::sort(result.projection.excludes.begin(),
              result.projection.excludes.end());
    if (result.projection.includes.size() >
            sync::kMaximumTreeV2SelectionRules ||
        result.projection.excludes.size() >
            sync::kMaximumTreeV2SelectionRules) {
        return Status{ErrorCode::resource_exhausted,
                      std::string(command) +
                          " selection rule class exceeds its bound"};
    }
    if (std::adjacent_find(result.projection.includes.begin(),
                           result.projection.includes.end()) !=
            result.projection.includes.end() ||
        std::adjacent_find(result.projection.excludes.begin(),
                           result.projection.excludes.end()) !=
            result.projection.excludes.end()) {
        return Status{ErrorCode::invalid_argument,
                      std::string(command) +
                          " selection rules are duplicated"};
    }
    return result;
}

struct ControlArguments {
    std::filesystem::path runtime{local::default_runtime_root()};
    std::filesystem::path sodium_library;
    std::filesystem::path argon2_library;
    std::filesystem::path wordlist;
    std::filesystem::path identity;
    std::chrono::milliseconds timeout{5000};
    bool from_start{false};
    std::optional<std::chrono::milliseconds> watch_for;
    std::chrono::milliseconds sample_interval{250};
    std::uint32_t failure_samples{3U};
    std::uint32_t recovery_samples{2U};
    std::vector<std::string_view> positional;
};

Result<ControlArguments> parse_control_arguments(std::span<const std::string_view> arguments) {
    ControlArguments parsed;
    for (std::size_t index = 0U; index < arguments.size(); ++index) {
        if (arguments[index] == "--runtime") {
            if (index + 1U >= arguments.size()) {
                return Status{ErrorCode::invalid_argument, "--runtime requires a path"};
            }
            parsed.runtime = arguments[++index];
            continue;
        }
        if (arguments[index] == "--sodium-library" ||
            arguments[index] == "--argon2-library" ||
            arguments[index] == "--wordlist" ||
            arguments[index] == "--identity") {
            const std::string_view option = arguments[index];
            if (index + 1U >= arguments.size()) {
                return Status{ErrorCode::invalid_argument,
                              std::string(option) + " requires a path"};
            }
            const std::filesystem::path path(arguments[++index]);
            if (option == "--sodium-library") {
                parsed.sodium_library = path;
            } else if (option == "--argon2-library") {
                parsed.argon2_library = path;
            } else if (option == "--identity") {
                parsed.identity = path;
            } else {
                parsed.wordlist = path;
            }
            continue;
        }
        if (arguments[index] == "--timeout-ms") {
            if (index + 1U >= arguments.size()) {
                return Status{ErrorCode::invalid_argument, "--timeout-ms requires a value"};
            }
            auto value = parse_u64(arguments[++index], "--timeout-ms");
            if (!value || value.value() == 0U || value.value() > 600000U) {
                return Status{ErrorCode::invalid_argument,
                              "--timeout-ms must be between 1 and 600000"};
            }
            parsed.timeout = std::chrono::milliseconds(value.value());
            continue;
        }
        if (arguments[index] == "--from-start") {
            parsed.from_start = true;
            continue;
        }
        if (arguments[index] == "--watch-ms") {
            if (index + 1U >= arguments.size()) {
                return Status{ErrorCode::invalid_argument,
                              "--watch-ms requires a value"};
            }
            auto value = parse_u64(arguments[++index], "--watch-ms");
            if (!value || value.value() == 0U || value.value() > 86400000U) {
                return Status{ErrorCode::invalid_argument,
                              "--watch-ms must be between 1 and 86400000"};
            }
            parsed.watch_for = std::chrono::milliseconds(value.value());
            continue;
        }
        if (arguments[index] == "--sample-ms") {
            if (index + 1U >= arguments.size()) {
                return Status{ErrorCode::invalid_argument,
                              "--sample-ms requires a value"};
            }
            auto value = parse_u64(arguments[++index], "--sample-ms");
            if (!value || value.value() < 100U || value.value() > 600000U) {
                return Status{ErrorCode::invalid_argument,
                              "--sample-ms must be between 100 and 600000"};
            }
            parsed.sample_interval = std::chrono::milliseconds(value.value());
            continue;
        }
        if (arguments[index] == "--failure-samples" ||
            arguments[index] == "--recovery-samples") {
            const std::string_view option = arguments[index];
            if (index + 1U >= arguments.size()) {
                return Status{ErrorCode::invalid_argument,
                              std::string(option) + " requires a value"};
            }
            auto value = parse_u64(arguments[++index], option);
            if (!value || value.value() == 0U || value.value() > 64U) {
                return Status{ErrorCode::invalid_argument,
                              std::string(option) + " must be between 1 and 64"};
            }
            if (option == "--failure-samples") {
                parsed.failure_samples =
                    static_cast<std::uint32_t>(value.value());
            } else {
                parsed.recovery_samples =
                    static_cast<std::uint32_t>(value.value());
            }
            continue;
        }
        parsed.positional.push_back(arguments[index]);
    }
    return parsed;
}

int print_response_error(const local::ControlPacket &response) {
    const std::string message = local::payload_text(response.payload);
    std::cerr << "error=" << local::to_string(response.status)
              << " message=" << message << '\n';
    if (auto hint = explanation_hint_for_text(message)) {
        std::cerr << "hint-command=iotox explain " << *hint << '\n';
    }
    return 4;
}

Result<local::ControlPacket> send_control(
    const ControlArguments &arguments, local::ControlPacket request) {
    return local::control_request(
        arguments.runtime / "control.sock", request, arguments.timeout);
}

Result<std::string> try_control_text(
    const ControlArguments &arguments, local::ControlOperation operation) {
    local::ControlPacket request;
    request.kind = local::ControlKind::request;
    request.operation = operation;
    request.request_id = next_request_id();
    auto response = send_control(arguments, std::move(request));
    if (!response) return response.status();
    if (response.value().status != ErrorCode::ok) {
        return Status{response.value().status,
                      local::payload_text(response.value().payload)};
    }
    return local::payload_text(response.value().payload);
}

std::map<std::string, std::string> parse_key_value_lines(
    std::string_view text) {
    std::map<std::string, std::string> values;
    std::size_t offset = 0U;
    while (offset <= text.size()) {
        const std::size_t end = text.find('\n', offset);
        const std::string_view line = text.substr(
            offset,
            end == std::string_view::npos ? std::string_view::npos
                                          : end - offset);
        const std::size_t separator = line.find('=');
        if (separator != std::string_view::npos && separator > 0U) {
            values.emplace(std::string(line.substr(0U, separator)),
                           std::string(line.substr(separator + 1U)));
        }
        if (end == std::string_view::npos) break;
        offset = end + 1U;
    }
    return values;
}

std::map<std::string, std::string> parse_key_value_tokens(
    std::string_view line) {
    std::map<std::string, std::string> values;
    std::size_t offset = 0U;
    while (offset < line.size()) {
        while (offset < line.size() && line[offset] == ' ') ++offset;
        const std::size_t end = line.find(' ', offset);
        const std::string_view token = line.substr(
            offset,
            end == std::string_view::npos ? std::string_view::npos
                                          : end - offset);
        const std::size_t separator = token.find('=');
        if (separator != std::string_view::npos && separator > 0U) {
            values.emplace(std::string(token.substr(0U, separator)),
                           std::string(token.substr(separator + 1U)));
        }
        if (end == std::string_view::npos) break;
        offset = end + 1U;
    }
    return values;
}

struct StableEvidenceBlocker {
    std::string name;
    std::string status;
};

struct StableEvidenceCheck {
    std::filesystem::path path;
    std::map<std::string, std::string> fields;
    std::vector<StableEvidenceBlocker> blockers;

    [[nodiscard]] bool accepted() const noexcept { return blockers.empty(); }
};

bool is_lower_hex_sha256(std::string_view value) noexcept {
    if (value.size() != 64U) return false;
    return std::all_of(value.begin(), value.end(), [](char character) {
        return (character >= '0' && character <= '9') ||
               (character >= 'a' && character <= 'f');
    });
}

constexpr std::size_t kStableEvidenceManifestMaxBytes = 64U * 1024U;
constexpr std::size_t kStableEvidenceReceiptMaxBytes = 1024U * 1024U;
constexpr std::uint64_t kStableTerminalLongSoakSeconds = 24U * 60U * 60U;
constexpr std::uint64_t kStableTerminalLongSoakMaxSampleGapSeconds = 15U * 60U;

bool is_backup_receipt_label(std::string_view value);
bool is_safe_operator_evidence_label(std::string_view value);
