int run_person_contact_upsert(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 5U) {
        std::cerr << "person contact-upsert requires CONTACT_BOOK NAME PERSON_CARD\n";
        return 2;
    }
    auto book_path =
        absolute_cli_path(positionals[2U], "person contact book");
    auto card_path =
        absolute_cli_path(positionals[4U], "person delivery card");
    if (!book_path || !card_path) {
        std::cerr << (!book_path ? book_path.status().message()
                                 : card_path.status().message())
                  << '\n';
        return 2;
    }
    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto card = person::load_delivery_card(card_path.value(), sodium.value());
    if (!card) {
        std::cerr << card.status().message() << '\n';
        return person_status_code(card.status());
    }
    auto entry = person::contact_entry_from_card(
        positionals[3U], card.value(), sodium.value());
    if (!entry) {
        std::cerr << entry.status().message() << '\n';
        return person_status_code(entry.status());
    }
    auto committed =
        person::commit_contact_entry(book_path.value(), entry.value());
    if (!committed) {
        std::cerr << committed.status().message() << '\n';
        return person_status_code(committed.status());
    }
    std::cout << "iotox-person-contact-upsert-v1\n"
              << "book=" << book_path.value().string() << '\n'
              << "card=" << card_path.value().string() << '\n'
              << person::render_contact_entry(committed.value())
              << "mutated=contact-book\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_contact_list(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 3U) {
        std::cerr << "person contact-list requires CONTACT_BOOK\n";
        return 2;
    }
    (void)control_arguments;
    auto book_path =
        absolute_cli_path(positionals[2U], "person contact book");
    if (!book_path) {
        std::cerr << book_path.status().message() << '\n';
        return 2;
    }
    auto book = person::load_contact_book(book_path.value());
    if (!book) {
        std::cerr << book.status().message() << '\n';
        return person_status_code(book.status());
    }
    std::cout << person::render_contact_book(book.value());
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

