int run_person_transcript_commit(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 5U) {
        std::cerr << "person transcript-commit requires TRANSCRIPT in|out PAYLOAD_HEX\n";
        return 2;
    }
    auto transcript_path =
        absolute_cli_path(positionals[2U], "person transcript");
    auto payload = person_payload_from_hex(positionals[4U]);
    if (!transcript_path || !payload) {
        std::cerr << (!transcript_path ? transcript_path.status().message()
                                       : payload.status().message())
                  << '\n';
        return 2;
    }
    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto entry = person::transcript_entry_from_payload(
        payload.value(), positionals[3U], sodium.value());
    if (!entry) {
        std::cerr << entry.status().message() << '\n';
        return person_status_code(entry.status());
    }
    auto committed =
        person::commit_transcript_entry(transcript_path.value(), entry.value());
    if (!committed) {
        std::cerr << committed.status().message() << '\n';
        return person_status_code(committed.status());
    }
    std::cout << "iotox-person-transcript-commit-v1\n"
              << "transcript=" << transcript_path.value().string() << '\n'
              << "sequence=" << committed.value().entry.sequence << '\n'
              << "duplicate=" << (committed.value().duplicate ? "1" : "0")
              << '\n'
              << "entries=" << committed.value().entries << '\n'
              << "direction=" << committed.value().entry.direction << '\n'
              << "scope=" << committed.value().entry.scope << '\n'
              << "from-person="
              << security::hex(committed.value().entry.from_person) << '\n';
    if (committed.value().entry.scope == "person") {
        std::cout << "to-person="
                  << security::hex(committed.value().entry.to_person) << '\n';
    } else {
        std::cout << "group="
                  << security::hex(committed.value().entry.group) << '\n';
    }
    std::cout << "message-id="
              << security::hex(committed.value().entry.message_id) << '\n'
              << "payload-digest="
              << security::hex(committed.value().entry.payload_digest) << '\n'
              << "body-bytes=" << committed.value().entry.body.size() << '\n'
              << "boundary=owner-private-contentful-transcript; duplicate-is-local-only\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

