int run_person_receipt_create_delegated(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 5U && positionals.size() != 6U) {
        std::cerr << "person receipt-create-delegated requires DELEGATION PAYLOAD_HEX RECEIPT [RECEIVED_UNIX_MS]\n";
        return 2;
    }
    auto delegation_path = absolute_cli_path(
        positionals[2U], "person sender delegation");
    auto receipt_path = absolute_cli_path(positionals[4U], "person receipt");
    auto payload = person_payload_from_hex(positionals[3U]);
    std::uint64_t received = unix_time_ms();
    if (positionals.size() == 6U) {
        auto parsed_received =
            parse_u64(positionals[5U], "receipt received-unix-ms");
        if (!parsed_received) {
            std::cerr << parsed_received.status().message() << '\n';
            return 2;
        }
        received = parsed_received.value();
    }
    if (!delegation_path || !receipt_path || !payload) {
        std::cerr << (!delegation_path ? delegation_path.status().message()
                         : !receipt_path ? receipt_path.status().message()
                                         : payload.status().message())
                  << '\n';
        return 2;
    }
    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto identity = load_cli_device_identity(control_arguments, sodium.value());
    if (!identity) {
        std::cerr << identity.status().message() << '\n';
        return person_status_code(identity.status());
    }
    auto delegation = person::load_sender_delegation(
        delegation_path.value(), sodium.value());
    if (!delegation) {
        std::cerr << delegation.status().message() << '\n';
        return person_status_code(delegation.status());
    }
    auto receipt = person::create_receipt_record(
        identity.value(), delegation.value(), payload.value(), received,
        sodium.value());
    if (!receipt) {
        std::cerr << receipt.status().message() << '\n';
        return person_status_code(receipt.status());
    }
    const Status written =
        person::create_receipt_record_file(receipt_path.value(),
                                           receipt.value());
    if (!written.ok()) {
        std::cerr << written.message() << '\n';
        return person_status_code(written);
    }
    std::cout << "iotox-person-receipt-create-v1\n"
              << "delegation=" << delegation_path.value().string() << '\n'
              << "receipt=" << receipt_path.value().string() << '\n'
              << person::render_receipt_record(receipt.value())
              << "mutated=1\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

