int run_person_receipt_commit(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 5U) {
        std::cerr << "person receipt-commit requires RECEIPT_STORE RECEIPT DELEGATION\n";
        return 2;
    }
    auto store_path =
        absolute_cli_path(positionals[2U], "person receipt store");
    auto receipt_path = absolute_cli_path(positionals[3U], "person receipt");
    auto delegation_path = absolute_cli_path(
        positionals[4U], "person sender delegation");
    if (!store_path || !receipt_path || !delegation_path) {
        std::cerr << (!store_path ? store_path.status().message()
                         : !receipt_path ? receipt_path.status().message()
                                         : delegation_path.status().message())
                  << '\n';
        return 2;
    }
    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto receipt =
        person::load_receipt_record(receipt_path.value(), sodium.value());
    auto delegation = person::load_sender_delegation(
        delegation_path.value(), sodium.value());
    if (!receipt || !delegation) {
        std::cerr << (!receipt ? receipt.status().message()
                               : delegation.status().message())
                  << '\n';
        return person_status_code(!receipt ? receipt.status()
                                           : delegation.status());
    }
    const Status verified = person::verify_receipt_record(
        receipt.value(), delegation.value(), sodium.value());
    if (!verified.ok()) {
        std::cerr << verified.message() << '\n';
        return person_status_code(verified);
    }
    auto committed = person::commit_receipt_record(
        store_path.value(), receipt.value(), sodium.value());
    if (!committed) {
        std::cerr << committed.status().message() << '\n';
        return person_status_code(committed.status());
    }
    std::cout << "iotox-person-receipt-commit-v1\n"
              << "store=" << store_path.value().string() << '\n'
              << "receipt=" << receipt_path.value().string() << '\n'
              << "scope=" << committed.value().receipt.scope << '\n'
              << "message-id="
              << security::hex(committed.value().receipt.message_id) << '\n'
              << "recipient-person="
              << security::hex(committed.value().receipt.recipient_person)
              << '\n'
              << "recipient-device="
              << security::hex(committed.value().receipt.recipient_device)
              << '\n'
              << "duplicate="
              << (committed.value().duplicate ? "1" : "0") << '\n'
              << "receipts=" << committed.value().receipts << '\n'
              << "mutated="
              << (committed.value().duplicate ? "0" : "receipt-store")
              << '\n'
              << "boundary=device-receipt-committed; aggregate-status-still-requires-explicit-expected-device-set\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_receipts_status(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() < 3U) {
        std::cerr << "person receipts-status requires RECEIPT_STORE [--message-id HEX] [--scope person|group] [--group HEX] [--expect-person HEX] [--expect-device HEX...]\n";
        return 2;
    }
    auto store_path =
        absolute_cli_path(positionals[2U], "person receipt store");
    if (!store_path) {
        std::cerr << store_path.status().message() << '\n';
        return 2;
    }
    std::optional<security::Digest> message_id;
    std::string scope{"any"};
    std::optional<security::Digest> group;
    std::optional<security::SigningPublicKey> expected_person;
    std::vector<security::SigningPublicKey> expected_devices;
    for (std::size_t index = 3U; index < positionals.size(); ++index) {
        const std::string_view option = positionals[index];
        if (option != "--message-id" && option != "--scope" &&
            option != "--group" && option != "--expect-person" &&
            option != "--expect-device") {
            std::cerr << "unknown person receipts-status option: "
                      << option << '\n';
            return 2;
        }
        if (++index >= positionals.size()) {
            std::cerr << option << " requires a value\n";
            return 2;
        }
        if (option == "--message-id") {
            auto parsed =
                parse_digest_argument(positionals[index], "receipt message id");
            if (!parsed) {
                std::cerr << parsed.status().message() << '\n';
                return 2;
            }
            message_id = parsed.value();
        } else if (option == "--scope") {
            if (positionals[index] != "person" &&
                positionals[index] != "group") {
                std::cerr << "person receipts-status --scope must be person or group\n";
                return 2;
            }
            scope = std::string(positionals[index]);
        } else if (option == "--group") {
            auto parsed =
                parse_digest_argument(positionals[index], "receipt group id");
            if (!parsed) {
                std::cerr << parsed.status().message() << '\n';
                return 2;
            }
            group = parsed.value();
        } else if (option == "--expect-person") {
            auto parsed = parse_signing_public_key(
                positionals[index], "expected receipt person");
            if (!parsed) {
                std::cerr << parsed.status().message() << '\n';
                return 2;
            }
            expected_person = parsed.value();
        } else {
            auto parsed = parse_signing_public_key(
                positionals[index], "expected receipt device");
            if (!parsed) {
                std::cerr << parsed.status().message() << '\n';
                return 2;
            }
            if (std::find(expected_devices.begin(), expected_devices.end(),
                          parsed.value()) != expected_devices.end()) {
                std::cerr << "person receipts-status repeats an expected device\n";
                return 2;
            }
            expected_devices.push_back(parsed.value());
        }
    }
    if (group && scope == "person") {
        std::cerr << "person receipts-status cannot combine --scope person with --group\n";
        return 2;
    }

    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    person::ReceiptStore store;
    auto loaded = person::load_receipt_store(store_path.value(), sodium.value());
    std::string store_status{"ok"};
    if (loaded) {
        store = std::move(loaded).value();
    } else if (loaded.status().code() == ErrorCode::not_found) {
        store_status = "absent";
    } else {
        std::cerr << loaded.status().message() << '\n';
        return person_status_code(loaded.status());
    }

    std::vector<person::ReceiptRecord> matching;
    for (const person::ReceiptRecord &receipt : store.receipts) {
        if (message_id && receipt.message_id != *message_id) continue;
        if (scope != "any" && receipt.scope != scope) continue;
        if (group && receipt.group != *group) continue;
        if (expected_person &&
            receipt.recipient_person != *expected_person) continue;
        matching.push_back(receipt);
    }

    std::size_t expected_received = 0U;
    for (const auto &device : expected_devices) {
        const bool found = std::any_of(
            matching.begin(), matching.end(),
            [&](const person::ReceiptRecord &receipt) {
                return receipt.recipient_device == device;
            });
        if (found) ++expected_received;
    }
    const bool complete =
        !expected_devices.empty() && expected_received == expected_devices.size();
    std::cout << "iotox-person-receipts-status-v1\n"
              << "store=" << store_path.value().string() << '\n'
              << "store-status=" << store_status << '\n'
              << "receipts=" << store.receipts.size() << '\n'
              << "matching-receipts=" << matching.size() << '\n'
              << "message-id="
              << (message_id ? security::hex(*message_id) : "any") << '\n'
              << "scope=" << scope << '\n'
              << "group=" << (group ? security::hex(*group) : "any")
              << '\n'
              << "expected-person="
              << (expected_person ? security::hex(*expected_person) : "any")
              << '\n'
              << "expected-devices=" << expected_devices.size() << '\n'
              << "expected-received-devices=" << expected_received << '\n'
              << "aggregate-complete=" << (complete ? "1" : "0") << '\n';
    for (const auto &device : expected_devices) {
        const bool found = std::any_of(
            matching.begin(), matching.end(),
            [&](const person::ReceiptRecord &receipt) {
                return receipt.recipient_device == device;
            });
        std::cout << "device=" << security::hex(device)
                  << " receipt=" << (found ? "present" : "missing") << '\n';
    }
    std::cout << "content-free=1\n"
              << "mutated=0\n"
              << "boundary=aggregate-device-receipts-only; person-read-status-and-cross-device-transcript-consensus-remain-explicit-higher-level-policy\n";
    if (!expected_devices.empty() && !complete) {
        return std::cout.good() ? 4 : 3;
    }
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_receive(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() < 3U) {
        std::cerr << "person receive requires PAYLOAD_HEX [--seen SEEN_STORE] "
                     "[--transcript TRANSCRIPT] [--direction in|out] "
                     "[--delegation DELEGATION --receipt RECEIPT] "
                     "[--receipt-store RECEIPT_STORE] "
                     "[--received-unix-ms N] [--dry-run]\n";
        return 2;
    }
    auto payload = person_payload_from_hex(positionals[2U]);
    if (!payload) {
        std::cerr << payload.status().message() << '\n';
        return 2;
    }
    std::optional<std::filesystem::path> seen_path;
    std::optional<std::filesystem::path> transcript_path;
    std::optional<std::filesystem::path> delegation_path;
    std::optional<std::filesystem::path> receipt_path;
    std::optional<std::filesystem::path> receipt_store_path;
    std::string direction{"in"};
    std::uint64_t received = unix_time_ms();
    bool dry_run = false;
    for (std::size_t index = 3U; index < positionals.size(); ++index) {
        const std::string_view option = positionals[index];
        if (option == "--dry-run") {
            dry_run = true;
            continue;
        }
        if (option != "--seen" && option != "--transcript" &&
            option != "--direction" && option != "--delegation" &&
            option != "--receipt" && option != "--receipt-store" &&
            option != "--received-unix-ms") {
            std::cerr << "unknown person receive option: " << option << '\n';
            return 2;
        }
        if (++index >= positionals.size()) {
            std::cerr << option << " requires a value\n";
            return 2;
        }
        if (option == "--direction") {
            if (positionals[index] != "in" && positionals[index] != "out") {
                std::cerr << "person receive --direction must be in or out\n";
                return 2;
            }
            direction = std::string(positionals[index]);
        } else if (option == "--received-unix-ms") {
            auto parsed = parse_u64(
                positionals[index], "person receive received-unix-ms");
            if (!parsed) {
                std::cerr << parsed.status().message() << '\n';
                return 2;
            }
            received = parsed.value();
        } else {
            const std::string_view label =
                option == "--seen"
                    ? "person seen store"
                    : option == "--transcript"
                          ? "person transcript"
                          : option == "--delegation"
                                ? "person sender delegation"
                          : option == "--receipt" ? "person receipt"
                                                   : "person receipt store";
            auto path = absolute_cli_path(positionals[index], label);
            if (!path) {
                std::cerr << path.status().message() << '\n';
                return 2;
            }
            if (option == "--seen") {
                if (seen_path) {
                    std::cerr << "person receive duplicates --seen\n";
                    return 2;
                }
                seen_path = path.value();
            } else if (option == "--transcript") {
                if (transcript_path) {
                    std::cerr << "person receive duplicates --transcript\n";
                    return 2;
                }
                transcript_path = path.value();
            } else if (option == "--delegation") {
                if (delegation_path) {
                    std::cerr << "person receive duplicates --delegation\n";
                    return 2;
                }
                delegation_path = path.value();
            } else if (option == "--receipt") {
                if (receipt_path) {
                    std::cerr << "person receive duplicates --receipt\n";
                    return 2;
                }
                receipt_path = path.value();
            } else {
                if (receipt_store_path) {
                    std::cerr << "person receive duplicates --receipt-store\n";
                    return 2;
                }
                receipt_store_path = path.value();
            }
        }
    }
    if (static_cast<bool>(delegation_path) !=
        static_cast<bool>(receipt_path)) {
        std::cerr << "person receive receipt creation requires both "
                     "--delegation and --receipt\n";
        return 2;
    }
    if (receipt_store_path && !receipt_path) {
        std::cerr << "person receive --receipt-store requires --receipt and --delegation\n";
        return 2;
    }
    if (receipt_path && direction != "in") {
        std::cerr << "person receive receipts are only valid for inbound "
                     "payloads\n";
        return 2;
    }

    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto transcript_entry = person::transcript_entry_from_payload(
        payload.value(), direction, sodium.value());
    if (!transcript_entry) {
        std::cerr << transcript_entry.status().message() << '\n';
        return person_status_code(transcript_entry.status());
    }
    auto seen_entry =
        person_seen_entry_from_payload(payload.value(), sodium.value());
    if (!seen_entry) {
        std::cerr << seen_entry.status().message() << '\n';
        return person_status_code(seen_entry.status());
    }

    std::optional<person::ReceiptRecord> receipt;
    if (receipt_path) {
        if (!dry_run) {
            std::error_code error;
            if (std::filesystem::exists(*receipt_path, error)) {
                std::cerr << "person receipt already exists: "
                          << receipt_path->string() << '\n';
                return 2;
            }
            if (error) {
                std::cerr << "unable to inspect person receipt path '"
                          << receipt_path->string() << "': "
                          << error.message() << '\n';
                return 3;
            }
        }
        auto identity =
            load_cli_device_identity(control_arguments, sodium.value());
        if (!identity) {
            std::cerr << identity.status().message() << '\n';
            return person_status_code(identity.status());
        }
        auto delegation = person::load_sender_delegation(
            *delegation_path, sodium.value());
        if (!delegation) {
            std::cerr << delegation.status().message() << '\n';
            return person_status_code(delegation.status());
        }
        auto created = person::create_receipt_record(
            identity.value(), delegation.value(), payload.value(), received,
            sodium.value());
        if (!created) {
            std::cerr << created.status().message() << '\n';
            return person_status_code(created.status());
        }
        receipt = created.value();
    }

    std::cout << "iotox-person-receive-v1\n"
              << "payload-bytes=" << payload.value().size() << '\n'
              << "direction=" << direction << '\n'
              << "scope=" << transcript_entry.value().scope << '\n'
              << "from-person="
              << security::hex(transcript_entry.value().from_person) << '\n';
    if (transcript_entry.value().scope == "person") {
        std::cout << "to-person="
                  << security::hex(transcript_entry.value().to_person) << '\n';
    } else {
        std::cout << "group="
                  << security::hex(transcript_entry.value().group) << '\n';
    }
    std::cout << "message-id="
              << security::hex(transcript_entry.value().message_id) << '\n'
              << "payload-digest="
              << security::hex(transcript_entry.value().payload_digest)
              << '\n'
              << "body-bytes=" << transcript_entry.value().body.size()
              << '\n'
              << "dry-run=" << (dry_run ? 1 : 0) << '\n';

    std::vector<std::string> mutated;
    if (transcript_path) {
        if (dry_run) {
            std::cout << "transcript=" << transcript_path->string()
                      << " status=planned\n";
        } else {
            auto committed = person::commit_transcript_entry(
                *transcript_path, transcript_entry.value());
            if (!committed) {
                std::cerr << committed.status().message() << '\n';
                return person_status_code(committed.status());
            }
            if (!committed.value().duplicate) mutated.emplace_back("transcript");
            std::cout << "transcript=" << transcript_path->string()
                      << " status=committed"
                      << " duplicate="
                      << (committed.value().duplicate ? "1" : "0")
                      << " sequence="
                      << committed.value().entry.sequence
                      << " entries=" << committed.value().entries << '\n';
        }
    } else {
        std::cout << "transcript=not-requested\n";
    }

    if (seen_path) {
        if (dry_run) {
            std::cout << "seen=" << seen_path->string()
                      << " status=planned\n";
        } else {
            auto committed = person::commit_seen_entry(
                *seen_path, seen_entry.value());
            if (!committed) {
                std::cerr << committed.status().message() << '\n';
                return person_status_code(committed.status());
            }
            if (!committed.value().duplicate) mutated.emplace_back("seen");
            std::cout << "seen=" << seen_path->string()
                      << " status=committed"
                      << " duplicate="
                      << (committed.value().duplicate ? "1" : "0")
                      << " entries=" << committed.value().entries << '\n';
        }
    } else {
        std::cout << "seen=not-requested\n";
    }

    if (receipt_path) {
        if (dry_run) {
            std::cout << "receipt=" << receipt_path->string()
                      << " status=planned\n";
            std::cout << "receipt-store="
                      << (receipt_store_path ? receipt_store_path->string()
                                             : "not-requested")
                      << " status="
                      << (receipt_store_path ? "planned" : "not-requested")
                      << '\n';
        } else {
            const Status written = person::create_receipt_record_file(
                *receipt_path, *receipt);
            if (!written.ok()) {
                std::cerr << written.message() << '\n';
                return person_status_code(written);
            }
            mutated.emplace_back("receipt");
            std::cout << "receipt=" << receipt_path->string()
                      << " status=created"
                      << " received-unix-ms=" << receipt->received_unix_ms
                      << '\n';
            if (receipt_store_path) {
                auto committed = person::commit_receipt_record(
                    *receipt_store_path, *receipt, sodium.value());
                if (!committed) {
                    std::cerr << committed.status().message() << '\n';
                    return person_status_code(committed.status());
                }
                if (!committed.value().duplicate) {
                    mutated.emplace_back("receipt-store");
                }
                std::cout << "receipt-store=" << receipt_store_path->string()
                          << " status=committed"
                          << " duplicate="
                          << (committed.value().duplicate ? "1" : "0")
                          << " receipts=" << committed.value().receipts
                          << '\n';
            } else {
                std::cout << "receipt-store=not-requested\n";
            }
        }
    } else {
        std::cout << "receipt=not-requested\n";
        std::cout << "receipt-store=not-requested\n";
    }

    std::cout << "mutated=";
    if (dry_run || mutated.empty()) {
        std::cout << '0';
    } else {
        for (std::size_t index = 0U; index < mutated.size(); ++index) {
            if (index != 0U) std::cout << ',';
            std::cout << mutated[index];
        }
    }
    std::cout << "\n"
              << "boundary=local-device-receive-state-only; not-all-device-delivery-or-transcript-consensus\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_messenger_status(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    (void)control_arguments;
    std::optional<std::filesystem::path> contacts_path;
    std::optional<std::filesystem::path> seen_path;
    std::optional<std::filesystem::path> transcript_path;
    std::optional<std::filesystem::path> outbox_path;
    std::optional<std::filesystem::path> receipts_path;
    for (std::size_t index = 2U; index < positionals.size(); ++index) {
        const std::string_view option = positionals[index];
        if (option != "--contacts" && option != "--seen" &&
            option != "--transcript" && option != "--outbox" &&
            option != "--receipts") {
            std::cerr << "unknown person messenger-status option: "
                      << option << '\n';
            return 2;
        }
        if (++index >= positionals.size()) {
            std::cerr << option << " requires a value\n";
            return 2;
        }
        auto path = absolute_cli_path(
            positionals[index],
            option == "--contacts"
                ? "person contact book"
                : option == "--seen"
                      ? "person seen store"
                      : option == "--transcript" ? "person transcript"
                      : option == "--outbox"    ? "person outbox"
                                                  : "person receipt store");
        if (!path) {
            std::cerr << path.status().message() << '\n';
            return 2;
        }
        if (option == "--contacts") {
            contacts_path = path.value();
        } else if (option == "--seen") {
            seen_path = path.value();
        } else if (option == "--transcript") {
            transcript_path = path.value();
        } else if (option == "--outbox") {
            outbox_path = path.value();
        } else {
            receipts_path = path.value();
        }
    }

    std::cout << "iotox-person-messenger-status-v1\n";
    if (contacts_path) {
        auto book = person::load_contact_book(*contacts_path);
        if (book) {
            std::size_t routes = 0U;
            for (const auto &entry : book.value().contacts) {
                routes += entry.routes.size();
            }
            std::cout << "contacts=" << contacts_path->string()
                      << " status=ok"
                      << " count=" << book.value().contacts.size()
                      << " routes=" << routes << '\n';
        } else if (book.status().code() == ErrorCode::not_found) {
            std::cout << "contacts=" << contacts_path->string()
                      << " status=absent count=0 routes=0\n";
        } else {
            std::cerr << book.status().message() << '\n';
            return person_status_code(book.status());
        }
    } else {
        std::cout << "contacts=not-requested\n";
    }

    if (seen_path) {
        auto store = person::load_seen_store(*seen_path);
        if (store) {
            std::cout << "seen=" << seen_path->string() << " status=ok"
                      << " entries=" << store.value().entries.size() << '\n';
        } else if (store.status().code() == ErrorCode::not_found) {
            std::cout << "seen=" << seen_path->string()
                      << " status=absent entries=0\n";
        } else {
            std::cerr << store.status().message() << '\n';
            return person_status_code(store.status());
        }
    } else {
        std::cout << "seen=not-requested\n";
    }

    if (transcript_path) {
        auto store = person::load_transcript_store(*transcript_path);
        if (store) {
            std::cout << "transcript=" << transcript_path->string()
                      << " status=ok"
                      << " entries=" << store.value().entries.size()
                      << " next-sequence=" << store.value().next_sequence
                      << '\n';
        } else if (store.status().code() == ErrorCode::not_found) {
            std::cout << "transcript=" << transcript_path->string()
                      << " status=absent entries=0 next-sequence=1\n";
        } else {
            std::cerr << store.status().message() << '\n';
            return person_status_code(store.status());
        }
    } else {
        std::cout << "transcript=not-requested\n";
    }

    if (outbox_path) {
        auto store = person::load_outbox_store(*outbox_path);
        if (store) {
            std::size_t pending = 0U;
            std::size_t sent = 0U;
            for (const person::OutboxItem &item : store.value().items) {
                pending += item.pending_routes.size();
                sent += item.sent_routes.size();
            }
            std::cout << "outbox=" << outbox_path->string() << " status=ok"
                      << " items=" << store.value().items.size()
                      << " pending-routes=" << pending
                      << " sent-routes=" << sent << '\n';
        } else if (store.status().code() == ErrorCode::not_found) {
            std::cout << "outbox=" << outbox_path->string()
                      << " status=absent items=0 pending-routes=0 sent-routes=0\n";
        } else {
            std::cerr << store.status().message() << '\n';
            return person_status_code(store.status());
        }
    } else {
        std::cout << "outbox=not-requested\n";
    }

    if (receipts_path) {
        auto sodium = load_cli_sodium(control_arguments);
        if (!sodium) {
            std::cerr << sodium.status().message() << '\n';
            return 3;
        }
        auto store = person::load_receipt_store(*receipts_path, sodium.value());
        if (store) {
            std::cout << "receipts=" << receipts_path->string()
                      << " status=ok"
                      << " entries=" << store.value().receipts.size()
                      << '\n';
        } else if (store.status().code() == ErrorCode::not_found) {
            std::cout << "receipts=" << receipts_path->string()
                      << " status=absent entries=0\n";
        } else {
            std::cerr << store.status().message() << '\n';
            return person_status_code(store.status());
        }
    } else {
        std::cout << "receipts=not-requested\n";
    }
    std::cout << "content-free=1\n"
              << "boundary=local-owner-private-store-health; not-remote-delivery-or-backup-proof\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

Result<std::size_t> parse_person_max_routes(
    std::string_view text,
    std::string_view label);

int run_person_messenger_plan(
    const ControlArguments &,
    std::span<const std::string_view> positionals) {
    std::optional<std::filesystem::path> contacts;
    std::optional<std::filesystem::path> seen;
    std::optional<std::filesystem::path> transcript;
    std::optional<std::filesystem::path> receipts;
    std::optional<std::filesystem::path> outbox;
    std::optional<std::filesystem::path> dead_letter;
    std::optional<std::filesystem::path> card;
    std::optional<std::filesystem::path> floor;
    std::size_t max_routes = 16U;
    std::uint64_t retry_every = 60U;
    std::uint64_t expire_after = 7U * 24U * 60U * 60U;
    for (std::size_t index = 2U; index < positionals.size(); ++index) {
        const std::string_view option = positionals[index];
        if (option != "--contacts" && option != "--seen" &&
            option != "--transcript" && option != "--receipts" &&
            option != "--outbox" && option != "--dead-letter" &&
            option != "--card" && option != "--floor" &&
            option != "--max-routes" && option != "--retry-every" &&
            option != "--expire-after") {
            std::cerr << "unknown person messenger-plan option: "
                      << option << '\n';
            return 2;
        }
        if (++index >= positionals.size()) {
            std::cerr << option << " requires a value\n";
            return 2;
        }
        if (option == "--max-routes") {
            auto parsed = parse_person_max_routes(positionals[index], option);
            if (!parsed) {
                std::cerr << parsed.status().message() << '\n';
                return 2;
            }
            max_routes = parsed.value();
        } else if (option == "--retry-every" || option == "--expire-after") {
            auto parsed = parse_u64(positionals[index], option);
            if (!parsed || parsed.value() == 0U ||
                parsed.value() > 30U * 24U * 60U * 60U) {
                std::cerr << (parsed ? std::string(option) +
                                        " must be 1..2592000 seconds"
                                      : parsed.status().message())
                          << '\n';
                return 2;
            }
            if (option == "--retry-every") retry_every = parsed.value();
            else expire_after = parsed.value();
        } else {
            auto path = absolute_cli_path(positionals[index], option);
            if (!path) {
                std::cerr << path.status().message() << '\n';
                return 2;
            }
            if (option == "--contacts") contacts = path.value();
            else if (option == "--seen") seen = path.value();
            else if (option == "--transcript") transcript = path.value();
            else if (option == "--receipts") receipts = path.value();
            else if (option == "--outbox") outbox = path.value();
            else if (option == "--dead-letter") dead_letter = path.value();
            else if (option == "--card") card = path.value();
            else floor = path.value();
        }
    }
    if (dead_letter && !outbox) {
        std::cerr << "person messenger-plan --dead-letter requires --outbox\n";
        return 2;
    }
    std::vector<std::string> status{"person", "messenger-status"};
    std::vector<std::string> background{"person", "background-plan"};
    std::vector<std::string> run{"person", "background-run"};
    const auto add_path = [](std::vector<std::string> &words,
                             std::string_view flag,
                             const std::optional<std::filesystem::path> &path) {
        if (path) {
            words.emplace_back(flag);
            words.emplace_back(path->string());
        }
    };
    for (auto *words : {&status, &background, &run}) {
        add_path(*words, "--contacts", contacts);
        add_path(*words, "--seen", seen);
        add_path(*words, "--transcript", transcript);
        add_path(*words, "--receipts", receipts);
        add_path(*words, "--outbox", outbox);
    }
    add_path(background, "--dead-letter", dead_letter);
    add_path(run, "--dead-letter", dead_letter);
    add_path(background, "--card", card);
    add_path(background, "--floor", floor);
    for (auto *words : {&background, &run}) {
        words->emplace_back("--max-routes");
        words->emplace_back(std::to_string(max_routes));
        words->emplace_back("--expire-after");
        words->emplace_back(std::to_string(expire_after));
    }
    background.emplace_back("--retry-every");
    background.emplace_back(std::to_string(retry_every));
    run.emplace_back("--cycles");
    run.emplace_back("1");
    run.emplace_back("--interval");
    run.emplace_back("0");

    std::cout << "iotox-person-messenger-plan-v1\n"
              << "messenger-status-command="
              << command_line(string_views(status)) << '\n'
              << "background-plan-command="
              << command_line(string_views(background)) << '\n'
              << "background-run-command="
              << command_line(string_views(run)) << '\n';
    if (outbox) {
        std::vector<std::string> retry{
            "person", "outbox-retry-plan", outbox->string(),
            "--max-routes", std::to_string(max_routes),
            "--retry-every", std::to_string(retry_every),
            "--expire-after", std::to_string(expire_after)};
        std::vector<std::string> expire{
            "person", "outbox-expire", outbox->string(),
            dead_letter ? dead_letter->string() : "PERSON.dead-letter.outbox",
            "--expire-after", std::to_string(expire_after)};
        std::cout << "outbox-retry-plan-command="
                  << command_line(string_views(retry)) << '\n'
                  << "outbox-expire-command="
                  << command_line(string_views(expire)) << '\n';
    }
    if (card) {
        std::vector<std::string> refresh{
            "person", "card-refresh-plan", card->string()};
        if (floor) {
            refresh.emplace_back("--floor");
            refresh.emplace_back(floor->string());
        }
        std::cout << "card-refresh-plan-command="
                  << command_line(string_views(refresh)) << '\n';
    }
    std::cout
        << "receive-command=iotox --identity DEVICE_ID person receive PAYLOAD_HEX";
    if (seen) std::cout << " --seen " << shell_quote(seen->string());
    if (transcript) {
        std::cout << " --transcript "
                  << shell_quote(transcript->string());
    }
    if (receipts) {
        std::cout << " --delegation DELEGATION --receipt MESSAGE.receipt --receipt-store "
                  << shell_quote(receipts->string());
    }
    std::cout << '\n'
              << "device-receipt-semantics=device-received-not-human-read\n"
              << "transcript-semantics=local-order-not-cross-device-consensus\n"
              << "group-semantics=signed-group-envelope-not-tox-groupchat-identity\n"
              << "offline-delivery=bounded-outbox-retry-expire-dead-letter\n"
              << "mutated=0\n"
              << "boundary=messenger-plan-only; delivery-receipts-and-human-read-semantics-remain-explicit\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

Result<person::ToxPublicKey> parse_tox_bridge_public_key(
    std::string_view hex, std::string_view label) {
    auto decoded = security::decode_hex_exact(
        hex, person::kToxPublicKeyBytes, label);
    if (!decoded) return decoded.status();
    person::ToxPublicKey key{};
    std::copy_n(decoded.value().begin(), person::kToxPublicKeyBytes,
                key.begin());
    return key;
}

Result<person::ToxPublicKey> current_runtime_tox_public_key(
    const ControlArguments &arguments) {
    auto address = try_control_text(arguments, local::ControlOperation::address);
    if (!address) return address.status();
    std::string compact;
    compact.reserve(address.value().size());
    for (const char c : address.value()) {
        if (c != '\n' && c != '\r' && c != '\t' && c != ' ') {
            compact.push_back(c);
        }
    }
    if (compact.size() != toxcore::abi::kAddressSize * 2U) {
        return Status{ErrorCode::protocol_error,
                      "current runtime returned a malformed Tox address"};
    }
    return parse_tox_bridge_public_key(
        std::string_view(compact).substr(0U, person::kToxPublicKeyBytes * 2U),
        "current runtime Tox public key");
}

Result<std::vector<std::uint8_t>> person_tox_bridge_body_from_arguments(
    std::span<const std::string_view> positionals,
    std::size_t begin) {
    if (positionals.size() <= begin) {
        return Status{ErrorCode::invalid_argument,
                      "person Tox bridge requires non-empty text"};
    }
    const std::string text = join_message(positionals.subspan(begin));
    std::vector<std::uint8_t> body(text.begin(), text.end());
    if (body.empty() ||
        body.size() > person::kMaximumMessageBodyBytes) {
        return Status{ErrorCode::invalid_argument,
                      "person Tox bridge body must contain 1..320 bytes"};
    }
    return body;
}

int run_person_tox_bridge_plan_or_send(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals,
    bool outbound,
    bool live) {
    std::optional<std::filesystem::path> bridge_store_path;
    std::size_t required_begin = 2U;
    if (positionals.size() > required_begin &&
        positionals[required_begin] == "--bridge-store") {
        if (positionals.size() <= required_begin + 1U) {
            std::cerr << "person " << positionals[1U]
                      << " --bridge-store requires BRIDGE_STORE\n";
            return 2;
        }
        auto parsed_bridge_store = absolute_cli_path(
            positionals[required_begin + 1U], "person Tox bridge store");
        if (!parsed_bridge_store) {
            std::cerr << parsed_bridge_store.status().message() << '\n';
            return 2;
        }
        bridge_store_path = parsed_bridge_store.value();
        required_begin += 2U;
    }
    if (positionals.size() < required_begin + 5U) {
        std::cerr
            << "person " << positionals[1U]
            << " requires [--bridge-store BRIDGE_STORE] SELF_CARD DELEGATION "
            << (outbound && live ? "EXTERNAL_FRIEND" : "EXTERNAL_TOX_KEY_HEX")
            << " message|action TEXT\n";
        return 2;
    }
    auto card_path = absolute_cli_path(
        positionals[required_begin], "person self delivery card");
    auto delegation_path = absolute_cli_path(
        positionals[required_begin + 1U], "person Tox bridge sender delegation");
    if (!card_path || !delegation_path) {
        std::cerr << (!card_path ? card_path.status().message()
                                 : delegation_path.status().message())
                  << '\n';
        return 2;
    }
    const std::string_view tox_kind = positionals[required_begin + 3U];
    if (tox_kind != "message" && tox_kind != "action") {
        std::cerr << "person Tox bridge kind must be message or action\n";
        return 2;
    }
    auto body = person_tox_bridge_body_from_arguments(
        positionals, required_begin + 4U);
    if (!body) {
        std::cerr << body.status().message() << '\n';
        return 2;
    }

    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto identity = load_cli_device_identity(control_arguments, sodium.value());
    if (!identity) {
        std::cerr << identity.status().message() << '\n';
        return person_status_code(identity.status());
    }
    auto card = person::load_delivery_card(card_path.value(), sodium.value());
    auto delegation =
        person::load_sender_delegation(delegation_path.value(), sodium.value());
    if (!card || !delegation) {
        std::cerr << (!card ? card.status().message()
                            : delegation.status().message())
                  << '\n';
        return person_status_code(!card ? card.status()
                                        : delegation.status());
    }
    if (card.value().person != delegation.value().person) {
        std::cerr << "person Tox bridge self card does not match delegation person\n";
        return 2;
    }

    person::ToxPublicKey external_key{};
    std::optional<std::uint32_t> external_friend_number;
    std::string external_selector{positionals[required_begin + 2U]};
    if (outbound && live) {
        auto public_key = resolve_friend_public_key(
            control_arguments, positionals[required_begin + 2U]);
        auto friend_number =
            resolve_friend_selector(control_arguments,
                                    positionals[required_begin + 2U]);
        if (!public_key || !friend_number) {
            std::cerr << (!public_key ? public_key.status().message()
                                      : friend_number.status().message())
                      << '\n';
            return 4;
        }
        if (public_key.value().size() != person::kToxPublicKeyBytes) {
            std::cerr << "resolved Tox friend key has unexpected length\n";
            return 4;
        }
        std::copy_n(public_key.value().begin(), person::kToxPublicKeyBytes,
                    external_key.begin());
        external_friend_number = friend_number.value();
    } else {
        auto parsed_key = parse_tox_bridge_public_key(
            positionals[required_begin + 2U],
            "person Tox bridge external Tox key");
        if (!parsed_key) {
            std::cerr << parsed_key.status().message() << '\n';
            return 2;
        }
        external_key = parsed_key.value();
        external_selector = "key:" + security::hex(external_key);
    }

    auto envelope = person::create_tox_bridge_message_envelope(
        identity.value(), delegation.value(), outbound ? "out" : "in",
        tox_kind, external_key, body.value(), unix_time_ms(), sodium.value());
    if (!envelope) {
        std::cerr << envelope.status().message() << '\n';
        return person_status_code(envelope.status());
    }
    auto encoded =
        person::encode_signed_tox_bridge_message_envelope(envelope.value());
    if (!encoded) {
        std::cerr << encoded.status().message() << '\n';
        return person_status_code(encoded.status());
    }
    if (encoded.value().size() > toxcore::abi::kMaxMessageLength) {
        std::cerr << "person Tox bridge envelope is outside the Tox text bound\n";
        return 2;
    }
    const std::string payload_hex = security::hex(encoded.value());
    const std::string body_hex = security::hex(body.value());

    struct Target {
        std::string route_hex;
        std::uint32_t friend_number{0U};
    };
    std::vector<Target> targets;
    std::vector<std::string> skipped_current_routes;
    targets.reserve(card.value().routes.size());
    if (live) {
        auto current_route = current_runtime_tox_public_key(control_arguments);
        if (!current_route) {
            std::cerr << "person Tox bridge cannot resolve current self route: "
                      << current_route.status().message() << '\n';
            return 4;
        }
        for (const person::DeliveryRouteKey &route : card.value().routes) {
            const std::string route_hex = security::hex(route);
            if (route == current_route.value()) {
                skipped_current_routes.push_back(route_hex);
                continue;
            }
            auto number =
                resolve_friend_selector(control_arguments, "key:" + route_hex);
            if (!number) {
                std::cerr << "person Tox bridge self route is not a current "
                             "Tox friend: "
                          << route_hex << ": "
                          << number.status().message() << '\n';
                return 4;
            }
            targets.push_back(Target{route_hex, number.value()});
        }
    }

    std::cout << (live ? "iotox-person-tox-bridge-send-v1\n"
                       : "iotox-person-tox-bridge-plan-v1\n")
              << "direction=" << (outbound ? "out" : "in") << '\n'
              << "tox-kind=" << tox_kind << '\n'
              << "self-card=" << card_path.value().string() << '\n'
              << "delegation=" << delegation_path.value().string() << '\n'
              << "observer-person="
              << security::hex(envelope.value().observer_person) << '\n'
              << "observer-device="
              << security::hex(envelope.value().observer_device) << '\n'
              << "external-tox-key=" << security::hex(external_key) << '\n'
              << "message-id="
              << security::hex(envelope.value().message_id) << '\n'
              << "body-bytes=" << body.value().size() << '\n'
              << "payload-bytes=" << encoded.value().size() << '\n'
              << "payload-hex=" << payload_hex << '\n'
              << "local-bridge-store="
              << (bridge_store_path ? bridge_store_path->string() : "none")
              << '\n'
              << "routes=" << card.value().routes.size() << '\n'
              << "route-policy=not-carried-by-person-card\n"
              << "route-policy-authority=route-set-v2-and-explicit-run-config\n"
              << "privacy-fallback=not-authorized-by-card\n"
              << "tox-bridge-route-qualification=default-qualified;forced-tcp-degraded;tor-i2p-open\n";

    if (outbound) {
        std::vector<std::string_view> normal_send{
            tox_kind == "action" ? "action-hex" : "message-hex",
            external_selector, body_hex};
        std::cout << "normal-tox-send-command="
                  << command_line(normal_send) << '\n';
    } else {
        std::cout << "normal-tox-send-command=not-applicable-inbound-already-observed\n";
    }

    if (!live) {
        for (const person::DeliveryRouteKey &route : card.value().routes) {
            const std::string route_hex = security::hex(route);
            const std::string selector = "key:" + route_hex;
            std::vector<std::string_view> send_words{
                "message-hex", selector, payload_hex};
            std::cout << "self-route=" << route_hex << '\n'
                      << "self-fanout-command="
                      << command_line(send_words) << '\n';
        }
        if (bridge_store_path) {
            const std::string delegation_string =
                delegation_path.value().string();
            const std::string bridge_store_string = bridge_store_path->string();
            std::vector<std::string_view> commit_words{
                "person", "tox-bridge-receive", payload_hex,
                delegation_string, bridge_store_string};
            std::cout << "local-bridge-commit-command="
                      << command_line(commit_words) << '\n';
        } else {
            std::cout << "local-bridge-commit-command=not-requested\n";
        }
        std::cout << "mutated=0\n"
                  << "boundary=normal-tox-compatibility-plan; external-tox-key-is-not-iotox-person-identity; route-class-policy-is-separate\n";
        return std::cout.good() ? EXIT_SUCCESS : 3;
    }

    if (outbound) {
        auto sent = send_person_text_payload(
            control_arguments, *external_friend_number, body.value(),
            tox_kind == "action");
        if (!sent) {
            std::cerr << "normal Tox bridge send failed: "
                      << sent.status().message() << '\n';
            return 4;
        }
        std::cout << "normal-tox-sent friend=" << *external_friend_number
                  << " transport-message-id=" << sent.value() << '\n';
    }
    for (const Target &target : targets) {
        auto sent = send_person_text_payload(
            control_arguments, target.friend_number, encoded.value());
        if (!sent) {
            std::cerr << "person Tox bridge self fanout failed: "
                      << target.route_hex << ": "
                      << sent.status().message() << '\n';
            return 4;
        }
        std::cout << "self-sent route=" << target.route_hex
                  << " friend=" << target.friend_number
                  << " transport-message-id=" << sent.value() << '\n';
    }
    for (const std::string &route_hex : skipped_current_routes) {
        std::cout << "self-skip route=" << route_hex
                  << " reason=current-runtime-route\n";
    }
    bool local_bridge_mutated = false;
    if (bridge_store_path) {
        auto entry = person::tox_bridge_entry_from_payload(
            encoded.value(), delegation.value(), sodium.value());
        if (!entry) {
            std::cerr << entry.status().message() << '\n';
            return person_status_code(entry.status());
        }
        auto committed =
            person::commit_tox_bridge_entry(*bridge_store_path, entry.value());
        if (!committed) {
            std::cerr << committed.status().message() << '\n';
            return person_status_code(committed.status());
        }
        local_bridge_mutated = !committed.value().duplicate;
        std::cout << "local-bridge=committed"
                  << " duplicate="
                  << (committed.value().duplicate ? "1" : "0")
                  << " sequence=" << committed.value().entry.sequence
                  << " entries=" << committed.value().entries << '\n';
    } else {
        std::cout << "local-bridge=not-requested\n";
    }
    std::string mutated =
        outbound ? "normal-tox-message,self-fanout" : "self-fanout";
    if (local_bridge_mutated) mutated += ",bridge-store";
    std::cout << "mutated=" << mutated
              << '\n'
              << "boundary=normal-tox-edge-compatibility; self-fanout-is-signed-observation-not-external-person-signature; route-class-policy-is-separate\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_tox_bridge_receive(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() < 5U || positionals.size() > 6U) {
        std::cerr << "person tox-bridge-receive requires PAYLOAD_HEX "
                     "DELEGATION BRIDGE_STORE [--dry-run]\n";
        return 2;
    }
    const bool dry_run = positionals.size() == 6U &&
                         positionals[5U] == "--dry-run";
    if (positionals.size() == 6U && !dry_run) {
        std::cerr << "unknown person tox-bridge-receive option: "
                  << positionals[5U] << '\n';
        return 2;
    }
    auto payload = person_payload_from_hex(positionals[2U]);
    auto delegation_path = absolute_cli_path(
        positionals[3U], "person Tox bridge sender delegation");
    auto store_path =
        absolute_cli_path(positionals[4U], "person Tox bridge store");
    if (!payload || !delegation_path || !store_path) {
        std::cerr << (!payload ? payload.status().message()
                         : !delegation_path ? delegation_path.status().message()
                                            : store_path.status().message())
                  << '\n';
        return 2;
    }
    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto delegation =
        person::load_sender_delegation(delegation_path.value(), sodium.value());
    if (!delegation) {
        std::cerr << delegation.status().message() << '\n';
        return person_status_code(delegation.status());
    }
    auto entry = person::tox_bridge_entry_from_payload(
        payload.value(), delegation.value(), sodium.value());
    if (!entry) {
        std::cerr << entry.status().message() << '\n';
        return person_status_code(entry.status());
    }
    std::cout << "iotox-person-tox-bridge-receive-v1\n"
              << "store=" << store_path.value().string() << '\n'
              << "direction=" << entry.value().direction << '\n'
              << "tox-kind=" << entry.value().tox_kind << '\n'
              << "observer-person="
              << security::hex(entry.value().observer_person) << '\n'
              << "observer-device="
              << security::hex(entry.value().observer_device) << '\n'
              << "external-tox-key="
              << security::hex(entry.value().external_tox_key) << '\n'
              << "message-id=" << security::hex(entry.value().message_id)
              << '\n'
              << "body-bytes=" << entry.value().body.size() << '\n'
              << "dry-run=" << (dry_run ? 1 : 0) << '\n';
    if (dry_run) {
        std::cout << "bridge=planned\n"
                  << "mutated=0\n";
    } else {
        auto committed = person::commit_tox_bridge_entry(
            store_path.value(), entry.value());
        if (!committed) {
            std::cerr << committed.status().message() << '\n';
            return person_status_code(committed.status());
        }
        std::cout << "bridge=committed"
                  << " duplicate="
                  << (committed.value().duplicate ? "1" : "0")
                  << " sequence=" << committed.value().entry.sequence
                  << " entries=" << committed.value().entries << '\n'
                  << "mutated="
                  << (committed.value().duplicate ? "0" : "bridge-store")
                  << '\n';
    }
    std::cout << "boundary=local-normal-tox-compatibility-log; not-iotox-person-sender-or-remote-read-receipt\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_tox_bridge_status(
    const ControlArguments &,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 3U) {
        std::cerr << "person tox-bridge-status requires BRIDGE_STORE\n";
        return 2;
    }
    auto store_path =
        absolute_cli_path(positionals[2U], "person Tox bridge store");
    if (!store_path) {
        std::cerr << store_path.status().message() << '\n';
        return 2;
    }
    auto store = person::load_tox_bridge_store(store_path.value());
    if (!store) {
        if (store.status().code() == ErrorCode::not_found) {
            std::cout << "iotox-person-tox-bridge-status-v1\n"
                      << "store=" << store_path.value().string() << '\n'
                      << "status=absent\n"
                      << "entries=0\n"
                      << "next-sequence=1\n"
                      << "content-free=1\n"
                      << "boundary=normal-tox-compatibility-log-status; absent-store-is-empty\n";
            return std::cout.good() ? EXIT_SUCCESS : 3;
        }
        std::cerr << store.status().message() << '\n';
        return person_status_code(store.status());
    }
    std::size_t inbound = 0U;
    std::size_t outbound = 0U;
    for (const person::ToxBridgeEntry &entry : store.value().entries) {
        if (entry.direction == "in") {
            ++inbound;
        } else if (entry.direction == "out") {
            ++outbound;
        }
    }
    std::cout << "iotox-person-tox-bridge-status-v1\n"
              << "store=" << store_path.value().string() << '\n'
              << "status=ok\n"
              << "entries=" << store.value().entries.size() << '\n'
              << "inbound=" << inbound << '\n'
              << "outbound=" << outbound << '\n'
              << "next-sequence=" << store.value().next_sequence << '\n'
              << "content-free=1\n"
              << "boundary=normal-tox-compatibility-log-status; contentful-body-is-not-printed\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_outbox_enqueue(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 5U) {
        std::cerr << "person outbox-enqueue requires OUTBOX PERSON_CARD PAYLOAD_HEX\n";
        return 2;
    }
    auto outbox_path = absolute_cli_path(positionals[2U], "person outbox");
    auto card_path =
        absolute_cli_path(positionals[3U], "person delivery card");
    auto payload = person_payload_from_hex(positionals[4U]);
    if (!outbox_path || !card_path || !payload) {
        std::cerr << (!outbox_path ? outbox_path.status().message()
                         : !card_path ? card_path.status().message()
                                      : payload.status().message())
                  << '\n';
        return 2;
    }
    auto sodium = load_cli_sodium(control_arguments);
    if (!sodium) {
        std::cerr << sodium.status().message() << '\n';
        return 3;
    }
    auto card = person::load_delivery_card(card_path.value(), sodium.value());
    if (!card) {
        std::cerr << card.status().message() << '\n';
        return person_status_code(card.status());
    }
    auto item = person::outbox_item_from_card(
        card.value(), payload.value(), sodium.value());
    if (!item) {
        std::cerr << item.status().message() << '\n';
        return person_status_code(item.status());
    }
    item.value().created_unix_ms = unix_time_ms();
    auto committed =
        person::commit_outbox_item(outbox_path.value(), item.value());
    if (!committed) {
        std::cerr << committed.status().message() << '\n';
        return person_status_code(committed.status());
    }
    std::cout << "iotox-person-outbox-enqueue-v1\n"
              << "outbox=" << outbox_path.value().string() << '\n'
              << "card=" << card_path.value().string() << '\n';
    print_outbox_item_summary(committed.value());
    std::cout << "mutated=outbox\n"
              << "boundary=durable-send-plan-created; run-outbox-plan-before-transport-send\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

int run_person_outbox_plan(
    const ControlArguments &control_arguments,
    std::span<const std::string_view> positionals) {
    if (positionals.size() != 3U) {
        std::cerr << "person outbox-plan requires OUTBOX\n";
        return 2;
    }
    (void)control_arguments;
    auto outbox_path = absolute_cli_path(positionals[2U], "person outbox");
    if (!outbox_path) {
        std::cerr << outbox_path.status().message() << '\n';
        return 2;
    }
    auto store = person::load_outbox_store(outbox_path.value());
    if (!store) {
        std::cerr << store.status().message() << '\n';
        return person_status_code(store.status());
    }
    std::cout << "iotox-person-outbox-plan-v1\n"
              << "outbox=" << outbox_path.value().string() << '\n'
              << "items=" << store.value().items.size() << '\n';
    std::size_t pending = 0U;
    for (const person::OutboxItem &item : store.value().items) {
        const std::string payload_hex = security::hex(item.payload);
        std::cout << "item message-id=" << security::hex(item.message_id)
                  << " recipient-person="
                  << security::hex(item.recipient_person)
                  << " pending-routes=" << item.pending_routes.size()
                  << " sent-routes=" << item.sent_routes.size() << '\n';
        for (const person::DeliveryRouteKey &route : item.pending_routes) {
            const std::string route_hex = security::hex(route);
            const std::string selector = "key:" + route_hex;
            std::vector<std::string_view> send_words{
                "message-hex", selector, payload_hex};
            std::cout << "route=" << route_hex << '\n'
                      << "send-command=" << command_line(send_words) << '\n'
                      << "mark-sent-command=iotox person outbox-mark-sent "
                      << shell_quote(outbox_path.value().string()) << ' '
                      << security::hex(item.message_id) << ' '
                      << route_hex << '\n';
            ++pending;
        }
    }
    std::cout << "pending-routes=" << pending << '\n'
              << "mutated=0\n"
              << "boundary=operator-reviewed-plan; send-success-must-be-marked-explicitly\n";
    return std::cout.good() ? EXIT_SUCCESS : 3;
}

