    if (command == "delegate-recall-stdin") {
        if (arguments.size() < 5U) {
            std::cerr << "person delegate-recall-stdin requires SELF_SWARM_ROSTER ALIAS DELEGATION [verification options]\n";
            return 2;
        }
        auto roster_path =
            absolute_cli_path(arguments[2U], "self-swarm roster");
        auto delegation_path = absolute_cli_path(
            arguments[4U], "person sender delegation");
        if (!roster_path || !delegation_path) {
            std::cerr << (!roster_path ? roster_path.status().message()
                                       : delegation_path.status().message())
                      << '\n';
            return 2;
        }
        const std::span<const std::string_view> option_span{
            arguments.data() + 5U, arguments.size() - 5U};
        auto options = parse_self_swarm_inspection_options(option_span);
        if (!options) {
            std::cerr << options.status().message() << '\n';
            return 2;
        }
        auto credentials = read_recall_owner_credentials(parsed.value());
        if (!credentials) {
            std::cerr << credentials.status().message() << '\n';
            return secret_operation_exit_code(credentials.status());
        }
        auto &sodium = credentials.value().sodium;
        auto &owner_keys = credentials.value().keys;
        auto roster = self_swarm::load_roster(roster_path.value(), sodium);
        if (!roster) {
            std::cerr << roster.status().message() << '\n';
            return self_swarm_status_code(roster.status());
        }
        if (roster.value().owner != owner_keys.public_key()) {
            std::cerr
                << "RecallRoot owner does not match self-swarm roster owner\n";
            return 2;
        }
        const Status inspected = inspect_self_swarm_cli(
            parsed.value(), roster.value(), options.value(), sodium);
        if (!inspected.ok()) {
            std::cerr << inspected.message() << '\n';
            return self_swarm_status_code(inspected);
        }
        auto delegation = person::sender_delegation_from_roster(
            roster.value(), arguments[3U], sodium);
        if (!delegation) {
            std::cerr << delegation.status().message() << '\n';
            return person_status_code(delegation.status());
        }
        const Status signed_status =
            person::sign_sender_delegation(
                delegation.value(), owner_keys, sodium);
        if (!signed_status.ok()) {
            std::cerr << signed_status.message() << '\n';
            return person_status_code(signed_status);
        }
        const Status written = person::create_sender_delegation_file(
            delegation_path.value(), delegation.value());
        if (!written.ok()) {
            std::cerr << written.message() << '\n';
            return person_status_code(written);
        }
        std::cout << "iotox-person-sender-delegation-create-v1\n"
                  << "roster=" << roster_path.value().string() << '\n'
                  << "delegation=" << delegation_path.value().string() << '\n'
                  << "alias=" << arguments[3U] << '\n'
                  << "person=" << security::hex(delegation.value().person)
                  << '\n'
                  << "device=" << security::hex(delegation.value().device)
                  << '\n'
                  << "generation=" << delegation.value().generation << '\n'
                  << "mutated=1\n"
                  << "boundary=device-may-speak-as-person-only-through-this-owner-signed-delegation\n";
        return std::cout.good() ? EXIT_SUCCESS : 3;
    }

