Result<std::pair<sync::SyncPolicyTree, security::Digest>>
load_sync_policy_management_tree(
    const Agent::Config &config, const security::DeviceIdentity &identity,
    const security::Sodium &sodium) {
    auto tree = sync::load_sync_policy_tree(
        config.sync.policy_store_root,
        static_cast<std::uint32_t>(::geteuid()), identity.public_key(),
        sodium);
    if (!tree) return tree.status();
    auto digest = sync::sync_policy_tree_digest(tree.value(), sodium);
    if (!digest) return digest.status();
    return std::pair<sync::SyncPolicyTree, security::Digest>{
        std::move(tree).value(), digest.value()};
}

